            "举例：阿司匹林(乙酰水杨酸)前药→水解释放水杨酸；缬更昔洛韦→更昔洛韦；依诺沙星类(酯化前药)。",
            "logP↑→脂溶性↑、易跨膜吸收但水溶性差；成盐/加成基可提高水溶性。",
