            "水分→费休氏(卡尔费休)法/甲苯法；干燥失重→恒重法；炽灼残渣→马弗炉灼烧。",
            "溶出度→转篮/桨法；含量均匀度→小剂量片每片一致性；崩解时限→吊篮法。"
